// Generated by scripts/split.py from cockpit/: edit there and run it again
import { expect, test } from 'claude-code/testing'
import type { Register } from 'claude-code'
import { INITIAL } from '../hooks/state'

const core: Register = on => {
  on('engine.create', async (_$, e, next) => ({ ...(await next(e)), cockpit: { set: async () => true, act: async () => null, tab: async () => true } }))
  // Core keeps the state under its atom's shape tag: { shape, value }
  // A change is written, then handed on to the test's hook beneath, which records it; so are the actions
  on('cockpit.set', async ($, e, next) => {
    const { value } = await $.state.get({ plugin: 'cockpit-core', key: 's' })
    await $.state.set({ plugin: 'cockpit-core', key: 's' }, { shape: 'ph-23', value: { ...(value?.value as object), ...(e.patch as object) } } as never)
    return next(e)
  })
  // The test's way to lay the state, which only its owner writes
  on('tool.call', { tool: 'Seed' as never }, async ($, e) => {
    await $.state.set({ plugin: 'cockpit-core', key: 's' }, { shape: 'ph-23', value: (e as unknown as { state: never }).state } as never)
    return { result: 'ok' }
  })
}
// What the tab reads that a session would have loaded by now
const SEED = {}
const PANE = { component: 'Pane', requestId: 'cockpit', props: { title: 'Cockpit', isFocused: true, bodyColumns: 72, placement: 'dock', scroll: { offset: 0, bodyRows: 60 }, view: {} } }

for (const surface of ['terminal', 'desktop'] as const) {
  test(`draws the files tab below core's header on ${surface}, only while it is open, and its presses reach core`, { plugins: [{ name: 'cockpit-core', register: core }] }, async ($, on) => {
    on('clock.now', async () => ({ value: 1_000_000 }))
    on('ui.toast', async () => ({ value: undefined }))
    on('ui.open', async () => ({ value: { isPlaced: true } }))
    on('process.run', async () => ({ value: { exitCode: 0, stdout: '', stderr: '' } }) as never)
    const asked: string[] = []
    on('cockpit.set' as never, (async () => (asked.push('set'), { value: true })) as never)
    on('cockpit.act' as never, (async (_: unknown, e: { name: string }) => (asked.push(e.name), { value: e.name === 'claim' })) as never)
    on('cockpit.tab' as never, (async () => ({ value: true })) as never)
    on('ui.render', async (_, e) => {
      const { Text } = _.ui.resolve(e)
      return <Text>CORE FRAME</Text>
    })
    await $.tool.call({ tool: 'Seed', state: { ...INITIAL, tab: 'overview' } } as never)
    const ui = await $.ui.mount({ plugin: 'cockpit-activity', surface, ...PANE } as never)
    expect(JSON.stringify(await ui.drawn())).not.toContain('"part":{"plugin":"cockpit-activity"')
    await $.tool.call({ tool: 'Seed', state: { ...INITIAL, ...SEED, tab: 'files' } } as never)
    const drawn = JSON.stringify(await ui.drawn())
    expect(drawn.indexOf('CORE FRAME')).toBeGreaterThan(-1)
    expect(drawn.indexOf('"part":{"plugin":"cockpit-activity"')).toBeGreaterThan(-1)
    const buttons = (await ui.findAll({ type: 'Button' })).filter(b => b.key)
    expect(buttons.length).toBeGreaterThan(0)
    await ui.press({ key: String(buttons[0]?.key) })
    expect(asked.length).toBeGreaterThan(0)
    await ui.unmount()
  })
}
